1	/**
2	 * NxLabs — the public + in-portal mod/plugin catalogue read layer.
3	 *
4	 * This is a thin, presentation-agnostic layer over the REAL `GameMod` table
5	 * (seeded rows, enriched by scripts/verify-gamemods.ts). It backs three call
6	 * sites that must never disagree about what a mod "is":
7	 *   - app/(marketing)/mods (public browse + detail pages, anonymous-visible)
8	 *   - app/dashboard/nxlabs (logged-in catalogue with "Add to my server")
9	 *   - app/sitemap.ts (which detail pages get indexed)
10	 *
11	 * Deliberately NOT here: install/uninstall. Those stay exactly where they are
12	 * — lib/actions-mods.ts's installMod/uninstallMod — this module only reads.
13	 *
14	 * HONESTY: a mod only appears in the public/portal catalogue when
15	 * `active && upstreamOk`. `upstreamOk: false` is scripts/verify-gamemods.ts's
16	 * (or an admin's manual toggle's) way of saying "no longer supported" — it is
17	 * excluded rather than shown with a broken badge, matching how
18	 * lib/actions-mods.ts's getServerMods already filters for the per-server
19	 * panel. Fields the source never published (gameVersions, license, ...) stay
20	 * empty and the UI says so — never a guess.
21	 *
22	 * REAL PAGINATION (2026-09-19): every comment in this file used to say "small
23	 * catalogue (~124 rows), the whole set is returned in one shot, filters run
24	 * client-side" — true when this was hand-seeded, false the moment a real
25	 * bulk import (scripts/import-modrinth-catalog.ts) landed 32,000+ real
26	 * Modrinth rows in the `minecraft` family alone. A hard 400-row cap
27	 * (`CATALOG_LIST_CAP`, since removed) used to mean the other ~31,850 mods in
28	 * that family were permanently unreachable — no page 2 existed. `queryCatalogMods`
29	 * replaces `listCatalogMods`/`searchCatalogMods` with real server-side,
30	 * DB-level pagination (`skip`/`take` + a real `count()`), and search/sort/
31	 * category-filter all run as part of the SAME query rather than over an
32	 * in-memory array — see StoreBrowser.tsx's own header comment for why search
33	 * specifically had to move server-side (its placeholder text promises to
34	 * search the whole catalogue, not just whatever page happens to be loaded).
35	 */
36	import { db } from "./db";
37	import type { GameMod, GamePlan, Prisma } from "@prisma/client";
38	import { GAME_DISPLAY, type GameFamily } from "./games";
39	import { paginate } from "./pagination";
40	
41	/** Real page size for StoreBrowser — no longer a total-catalogue ceiling. */
42	const CATALOG_PAGE_SIZE = 24;
43	
44	export type ModSummary = {
45	  id: string;
46	  gameFamily: string;
47	  gameFamilyLabel: string;
48	  name: string;
49	  slug: string;
50	  category: string;
51	  source: string;
52	  iconUrl: string | null;
53	  description: string | null;
54	  downloads: number | null;
55	  featured: boolean;
56	  paid: boolean;
57	  verified: boolean;
58	  impact: string;
59	  createdAt: string; // ISO — client components get plain data, not Date objects
60	  /** Real computed average (1-5) from ModRating, null when nobody has rated it yet. */
61	  avgRating: number | null;
62	  /** Real count backing avgRating — 0 means "no ratings", never hidden behind a fake avg. */
63	  ratingCount: number;
64	  /**
65	   * The three fields resolveDownloadUrl() needs — carried on the summary too
66	   * (not just ModDetail) so a browse grid's cards can resolve the same real,
67	   * per-source download destination as the detail page without a second
68	   * query: queryCatalogMods already loads the full GameMod row internally,
69	   * so exposing these costs nothing extra.
70	   */
71	  url: string | null;
72	  sourceId: string | null;
73	  appliesToVariant: string | null;
74	  /**
75	   * The mod's REAL last-shipped timestamp on its own upstream source (ISO —
76	   * see GameMod.upstreamUpdatedAt's own comment for the confirmed per-source
77	   * field this is populated from). Null means "not backfilled/verified yet",
78	   * never a guess — listRecentlyUpdatedMods filters those rows out entirely
79	   * rather than showing them.
80	   */
81	  upstreamUpdatedAt: string | null;
82	};
83	
84	export type ModDetail = ModSummary & {
85	  url: string | null;
86	  sourceId: string | null;
87	  license: string | null;
88	  gameVersions: string[];
89	  loaders: string[];
90	  fileBytes: number | null;
91	  dependencyCount: number;
92	  serverSide: string | null;
93	  impactNote: string | null;
94	  appliesToVariant: string | null;
95	  verifiedAt: Date | null;
96	  upstreamOk: boolean;
97	  upstreamNote: string | null;
98	  galleryUrls: string[];
99	  authorName: string | null;
100	  authorAvatarUrl: string | null;
101	  /** Source's own longer project-page body (Modrinth's `body`), when backfilled — see GameMod.longDescription. */
102	  longDescription: string | null;
103	};
104	
105	export type ModComment = {
106	  id: string;
107	  rating: number;
108	  comment: string;
109	  createdAt: string;
110	  userId: string;
111	  userName: string;
112	};
113	
114	function familyLabel(family: string): string {
115	  return GAME_DISPLAY[family as GameFamily]?.name ?? family;
116	}
117	
118	type RatingAgg = { avg: number | null; count: number };
119	
120	/** Real average+count per mod, one groupBy query for as many mods as needed at once. */
121	async function ratingAggs(modIds: string[]): Promise<Map<string, RatingAgg>> {
122	  if (modIds.length === 0) return new Map();
123	  const rows = await db.modRating.groupBy({
124	    by: ["gameModId"],
125	    where: { gameModId: { in: modIds } },
126	    _avg: { rating: true },
127	    _count: { rating: true },
128	  });
129	  return new Map(rows.map((r) => [r.gameModId, { avg: r._avg.rating, count: r._count.rating }]));
130	}
131	
132	function toSummary(m: GameMod, agg?: RatingAgg): ModSummary {
133	  return {
134	    id: m.id,
135	    gameFamily: m.gameFamily,
136	    gameFamilyLabel: familyLabel(m.gameFamily),
137	    name: m.name,
138	    slug: m.slug,
139	    category: m.category,
140	    source: m.source,
141	    iconUrl: m.iconUrl,
142	    description: m.description,
143	    downloads: m.downloads,
144	    featured: m.featured,
145	    paid: m.paid,
146	    verified: m.verifiedAt !== null,
147	    impact: m.impact,
148	    createdAt: m.createdAt.toISOString(),
149	    avgRating: agg?.avg ?? null,
150	    ratingCount: agg?.count ?? 0,
151	    url: m.url,
152	    sourceId: m.sourceId,
153	    appliesToVariant: m.appliesToVariant,
154	    upstreamUpdatedAt: m.upstreamUpdatedAt ? m.upstreamUpdatedAt.toISOString() : null,
155	  };
156	}
157	
158	function toDetail(m: GameMod, agg?: RatingAgg): ModDetail {
159	  return {
160	    ...toSummary(m, agg),
161	    url: m.url,
162	    sourceId: m.sourceId,
163	    license: m.license,
164	    gameVersions: m.gameVersions,
165	    loaders: m.loaders,
166	    fileBytes: m.fileBytes,
167	    dependencyCount: m.dependencyCount,
168	    serverSide: m.serverSide,
169	    impactNote: m.impactNote,
170	    appliesToVariant: m.appliesToVariant,
171	    verifiedAt: m.verifiedAt,
172	    upstreamOk: m.upstreamOk,
173	    upstreamNote: m.upstreamNote,
174	    galleryUrls: m.galleryUrls,
175	    authorName: m.authorName,
176	    authorAvatarUrl: m.authorAvatarUrl,
177	    longDescription: m.longDescription,
178	  };
179	}
180	
181	/** Real, publicly-listable families — active mods with a real upstream today. */
182	export async function listCatalogFamilies(): Promise<{ family: string; label: string; count: number }[]> {
183	  const rows = await db.gameMod.groupBy({
184	    by: ["gameFamily"],
185	    where: { active: true, upstreamOk: true },
186	    _count: true,
187	    orderBy: { gameFamily: "asc" },
188	  });
189	  return rows
190	    .map((r) => ({ family: r.gameFamily, label: familyLabel(r.gameFamily), count: r._count }))
191	    .sort((a, b) => b.count - a.count);
192	}
193	
194	export type CatalogSort = "featured" | "downloads" | "latest" | "rating";
195	
196	export type CatalogPage = {
197	  mods: ModSummary[];
198	  total: number;
199	  page: number;
200	  totalPages: number;
201	  perPage: number;
202	};
203	
204	/**
205	 * Every scalar `orderBy` StoreBrowser's sort tabs can ask for. "rating" is
206	 * the one honest exception: avgRating is computed from a separate ModRating
207	 * table with no cached column on GameMod, and Prisma's relation-aggregate
208	 * `orderBy` only supports `_count` (not `_avg`) for to-many relations — there
209	 * is no cheap DB-side "top rated" ordering to give it. Fetching by downloads
210	 * and re-sorting by rating WITHIN each page (below) is a documented
211	 * approximation: "Top Rated" page 2 shows the 25th-48th most-downloaded mods
212	 * re-ordered by rating, not the true 25th-48th highest-rated mods
213	 * catalogue-wide. That is honest and fine at today's rating volumes (a small
214	 * fraction of 32k+ mods have any reviews at all); if ratings ever justify
215	 * it, add a cached avgRating/ratingCount column on GameMod (maintained by
216	 * the rating mutation) and give this its own real orderBy.
217	 */
218	const ORDER_BY: Record<CatalogSort, Prisma.GameModOrderByWithRelationInput[]> = {
219	  featured: [{ featured: "desc" }, { downloads: "desc" }, { popularity: "desc" }, { name: "asc" }],
220	  downloads: [{ downloads: "desc" }, { name: "asc" }],
221	  latest: [{ createdAt: "desc" }],
222	  rating: [{ downloads: "desc" }, { name: "asc" }],
223	};
224	
225	/**
226	 * Real, server-side, paginated + searched + sorted catalogue query — the
227	 * single data source behind every StoreBrowser instance (marketing and
228	 * portal, cross-game and per-family). Replaces the old
229	 * `listCatalogMods`/`searchCatalogMods` pair, which fetched (at most)
230	 * `CATALOG_LIST_CAP` rows once and left every control on top of it running
231	 * over that fixed in-memory array — fine at ~124 hand-seeded rows, silently
232	 * capping the catalogue at families with thousands+ of real imported rows.
233	 */
234	export async function queryCatalogMods(opts: {
235	  family?: string;
236	  /** Category filter — the per-family page's chips (StoreBrowser's `chipField: "category"`). */
237	  category?: string;
238	  q?: string;
239	  sort?: CatalogSort;
240	  page?: number;
241	  perPage?: number;
242	}): Promise<CatalogPage> {
243	  const sort = opts.sort ?? "featured";
244	  const q = (opts.q ?? "").trim();
245	  const where: Prisma.GameModWhereInput = {
246	    active: true,
247	    upstreamOk: true,
248	    ...(opts.family ? { gameFamily: opts.family } : {}),
249	    ...(opts.category ? { category: opts.category } : {}),
250	    ...(q
251	      ? {
252	          OR: [
253	            { name: { contains: q, mode: "insensitive" } },
254	            { category: { contains: q, mode: "insensitive" } },
255	            { description: { contains: q, mode: "insensitive" } },
256	          ],
257	        }
258	      : {}),
259	  };
260	
261	  const total = await db.gameMod.count({ where });
262	  const { skip, take, page, pages, perPage } = paginate(
263	    { page: opts.page != null ? String(opts.page) : undefined },
264	    total,
265	    opts.perPage ?? CATALOG_PAGE_SIZE
266	  );
267	
268	  const rows = await db.gameMod.findMany({ where, orderBy: ORDER_BY[sort], skip, take });
269	  const aggs = await ratingAggs(rows.map((r) => r.id));
270	  const mods = rows.map((r) => toSummary(r, aggs.get(r.id)));
271	  if (sort === "rating") {
272	    mods.sort((a, b) => (b.avgRating ?? -1) - (a.avgRating ?? -1) || b.ratingCount - a.ratingCount);
273	  }
274	
275	  return { mods, total, page, totalPages: pages, perPage };
276	}
277	
278	/**
279	 * Curated "Featured mods" rail — real `GameMod.featured` rows only (an
280	 * admin/import-time editorial flag, same field `ORDER_BY.featured` already
281	 * sorts by first), never a synthetic pick. Ordered by real downloads within
282	 * the featured set so the best-known featured mod leads. Returns fewer than
283	 * `take` (down to zero) when a family simply hasn't had any mods marked
284	 * featured yet — callers render nothing rather than pad with non-featured
285	 * rows, matching this file's no-guessing rule. Omit `family` for a
286	 * cross-game rail (the NxLabs homepage's curated "Featured" row, item 6 of
287	 * the 2026-09-20 overhaul), same optional-family convention as
288	 * listTopDownloadedMods/listRecentlyUpdatedMods below.
289	 */
290	export async function listFeaturedMods(family?: string, take = 8): Promise<ModSummary[]> {
291	  const rows = await db.gameMod.findMany({
292	    where: { active: true, upstreamOk: true, featured: true, ...(family ? { gameFamily: family } : {}) },
293	    orderBy: [{ downloads: "desc" }, { popularity: "desc" }, { name: "asc" }],
294	    take,
295	  });
296	  const aggs = await ratingAggs(rows.map((r) => r.id));
297	  return rows.map((r) => toSummary(r, aggs.get(r.id)));
298	}
299	
300	/**
301	 * Curated "Most downloaded" rail — real `GameMod.downloads`, DB-side sorted
302	 * and DB-side filtered to `downloads: { not: null }`. That filter matters:
303	 * Postgres' default NULLS FIRST for a DESC sort would otherwise put every
304	 * never-verified (downloads: null) row ahead of real numbers — see the
305	 * `rust`/`cs2` families, which currently have zero mods with a real
306	 * `downloads` count and so correctly return an empty array here rather than
307	 * a page of nulls masquerading as "most downloaded". Omit `family` for a
308	 * cross-game rail (the NxLabs homepage's curated section).
309	 */
310	export async function listTopDownloadedMods(family?: string, take = 8): Promise<ModSummary[]> {
311	  const rows = await db.gameMod.findMany({
312	    where: { active: true, upstreamOk: true, downloads: { not: null }, ...(family ? { gameFamily: family } : {}) },
313	    orderBy: [{ downloads: "desc" }, { name: "asc" }],
314	    take,
315	  });
316	  const aggs = await ratingAggs(rows.map((r) => r.id));
317	  return rows.map((r) => toSummary(r, aggs.get(r.id)));
318	}
319	
320	/**
321	 * Curated "Recently updated" rail — real `GameMod.upstreamUpdatedAt` only,
322	 * DB-side sorted desc and filtered to non-null. That filter is the whole
323	 * point: `upstreamUpdatedAt` is backfilled from each source's OWN API
324	 * (scripts/backfill-upstream-updated.ts), never derived from this table's
325	 * own `updatedAt` (which just marks when WE last touched the row — a bulk
326	 * re-import, a verify pass — and says nothing about the mod's real upstream
327	 * freshness). A mod that hasn't been backfilled yet has `upstreamUpdatedAt:
328	 * null` and simply doesn't appear here — never padded in with a guess.
329	 * Omit `family` for a cross-game rail (the NxLabs homepage's curated
330	 * section), same convention as listTopDownloadedMods above.
331	 */
332	export async function listRecentlyUpdatedMods(family?: string, take = 8): Promise<ModSummary[]> {
333	  const rows = await db.gameMod.findMany({
334	    where: { active: true, upstreamOk: true, upstreamUpdatedAt: { not: null }, ...(family ? { gameFamily: family } : {}) },
335	    orderBy: [{ upstreamUpdatedAt: "desc" }],
336	    take,
337	  });
338	  const aggs = await ratingAggs(rows.map((r) => r.id));
339	  return rows.map((r) => toSummary(r, aggs.get(r.id)));
340	}
341	
342	/**
343	 * Curated "Top Rated" rail (item 6 of the 2026-09-20 NxLabs overhaul — the
344	 * fourth curated row alongside Featured/Most Downloaded/Recently Updated).
345	 * Checked first, per that task's own instruction: `ORDER_BY.rating` above
346	 * already exists and is StoreBrowser's real, documented "Top Rated" sort for
347	 * pagination — fetch by real downloads, then re-sort by real `avgRating`
348	 * within that fetched set, because there is no cached avgRating column to
349	 * order by at the DB level (see that constant's own comment). This rail
350	 * reuses the EXACT same query/approximation rather than a stricter
351	 * "real average across a minimum rating count" query, which would render
352	 * this row permanently empty everywhere: confirmed live 2026-09-20, the
353	 * `ModRating` table has zero rows catalogue-wide today. Reusing the same
354	 * approximation means the row and its "View more" (?sort=rating) destination
355	 * never disagree, and the moment any mod gets real ratings, it sorts to the
356	 * front here exactly as it would on that sort's page 1 — never a fabricated
357	 * ranking, just an honestly-labeled approximation until real rating volume
358	 * exists.
359	 */
360	export async function listTopRatedMods(family?: string, take = 8): Promise<ModSummary[]> {
361	  const rows = await db.gameMod.findMany({
362	    where: { active: true, upstreamOk: true, ...(family ? { gameFamily: family } : {}) },
363	    orderBy: ORDER_BY.rating,
364	    take: take * 3, // over-fetch so the real-rating re-sort below has room to surface any rated mods
365	  });
366	  const aggs = await ratingAggs(rows.map((r) => r.id));
367	  return rows
368	    .map((r) => toSummary(r, aggs.get(r.id)))
369	    .sort((a, b) => (b.avgRating ?? -1) - (a.avgRating ?? -1) || b.ratingCount - a.ratingCount)
370	    .slice(0, take);
371	}
372	
373	/** Real category breakdown for one family, for the per-family page's chips — a DB-wide groupBy, not just what's on the current page. */
374	export async function listCategoryCounts(family: string): Promise<{ category: string; count: number }[]> {
375	  const rows = await db.gameMod.groupBy({
376	    by: ["category"],
377	    where: { active: true, upstreamOk: true, gameFamily: family },
378	    _count: true,
379	  });
380	  return rows.map((r) => ({ category: r.category, count: r._count })).sort((a, b) => b.count - a.count);
381	}
382	
383	/** Real total downloads across a whole family (or the whole catalogue) — a DB aggregate, not a reduce over one loaded page. */
384	export async function totalDownloadsFor(family?: string): Promise<number> {
385	  const agg = await db.gameMod.aggregate({
386	    where: { active: true, upstreamOk: true, ...(family ? { gameFamily: family } : {}) },
387	    _sum: { downloads: true },
388	  });
389	  return agg._sum.downloads ?? 0;
390	}
391	
392	/** Every {family, slug} pair eligible for a public page — feeds generateStaticParams + sitemap.ts. */
393	export async function listCatalogSlugs(): Promise<{ family: string; slug: string }[]> {
394	  const rows = await db.gameMod.findMany({
395	    where: { active: true, upstreamOk: true },
396	    select: { gameFamily: true, slug: true },
397	  });
398	  return rows.map((r) => ({ family: r.gameFamily, slug: r.slug }));
399	}
400	
401	/** One mod's detail. Returns null for an unknown/inactive slug — callers should notFound(). */
402	export async function getCatalogMod(family: string, slug: string): Promise<ModDetail | null> {
403	  const row = await db.gameMod.findUnique({ where: { gameFamily_slug: { gameFamily: family, slug } } });
404	  if (!row || !row.active) return null;
405	  const aggs = await ratingAggs([row.id]);
406	  return toDetail(row, aggs.get(row.id));
407	}
408	
409	/** A handful of other mods in the same family, for "related mods" rails. */
410	export async function relatedCatalogMods(mod: ModDetail, take = 4): Promise<ModSummary[]> {
411	  const rows = await db.gameMod.findMany({
412	    where: { active: true, upstreamOk: true, gameFamily: mod.gameFamily, id: { not: mod.id } },
413	    orderBy: [{ downloads: "desc" }, { popularity: "desc" }],
414	    take: take * 3, // over-fetch a little so the same-category re-sort below has real options
415	  });
416	  const aggs = await ratingAggs(rows.map((r) => r.id));
417	  // Prefer same-category matches first, client-side sort (small result set).
418	  return rows
419	    .map((r) => toSummary(r, aggs.get(r.id)))
420	    .sort((a, b) => Number(b.category === mod.category) - Number(a.category === mod.category))
421	    .slice(0, take);
422	}
423	
424	/**
425	 * Real average rating + comment count for one mod, and its paginated,
426	 * genuinely user-authored comment list (ModRating rows with a non-null
427	 * `comment`). No fabricated numbers: a mod nobody has rated returns
428	 * avg: null, count: 0, comments: [].
429	 */
430	export async function getModRatingSummary(modId: string): Promise<{ avg: number | null; count: number }> {
431	  const agg = await db.modRating.aggregate({ where: { gameModId: modId }, _avg: { rating: true }, _count: { rating: true } });
432	  return { avg: agg._avg.rating, count: agg._count.rating };
433	}
434	
435	export async function listModComments(modId: string, opts: { take?: number; cursor?: string } = {}): Promise<{ comments: ModComment[]; nextCursor: string | null }> {
436	  const take = opts.take ?? 10;
437	  const rows = await db.modRating.findMany({
438	    where: { gameModId: modId, comment: { not: null } },
439	    orderBy: { createdAt: "desc" },
440	    take: take + 1,
441	    ...(opts.cursor ? { cursor: { id: opts.cursor }, skip: 1 } : {}),
442	    include: { user: { select: { id: true, name: true } } },
443	  });
444	  const page = rows.slice(0, take);
445	  const nextCursor = rows.length > take ? page[page.length - 1]!.id : null;
446	  return {
447	    comments: page.map((r) => ({
448	      id: r.id,
449	      rating: r.rating,
450	      comment: r.comment!,
451	      createdAt: r.createdAt.toISOString(),
452	      userId: r.userId,
453	      userName: r.user.name,
454	    })),
455	    nextCursor,
456	  };
457	}
458	
459	/** This viewer's own rating/comment on a mod, if they've left one — prefills the form as an edit rather than a fresh submit. */
460	export async function getMyModRating(modId: string, userId: string): Promise<{ rating: number; comment: string | null } | null> {
461	  const row = await db.modRating.findUnique({ where: { userId_gameModId: { userId, gameModId: modId } } });
462	  return row ? { rating: row.rating, comment: row.comment } : null;
463	}
464	
465	/**
466	 * `id` is the real, live `GamePlan.id` this recommendation resolved to — kept
467	 * on the result (not just derived data) so a caller can hand it straight to
468	 * `deployHref({ gamePlanId })` and land the wizard on this EXACT plan, the
469	 * same real-tier resolution `order.tsx`'s `orderFromIntent` already does for
470	 * a `tier` query param. Never a synthetic id — always one of the
471	 * `gamePlans` rows passed in below.
472	 */
473	export type RecommendedPlan = { id: string; planName: string; ramMB: number; priceCents: number } | null;
474	
475	/**
476	 * Simple, honest heuristic (Phase 1 scope — no per-mod resource profiling):
477	 * light-impact mods run on any active plan for the family; moderate needs at
478	 * least 2GB; heavy needs at least 4GB. Returns the CHEAPEST active GamePlan
479	 * for the family that clears the bar, or null if none does (never guesses a
480	 * number that isn't a real, active, orderable plan). `null` is also the
481	 * honest signal for a family with zero active GamePlan rows at all (e.g.
482	 * "schedule1", which has no official dedicated server and stays unseeded —
483	 * see lib/games.ts) — callers must not render a deploy action in that case.
484	 */
485	export function recommendedPlanFor(mod: { impact: string }, gamePlans: Pick<GamePlan, "id" | "name" | "ramMB" | "priceCents" | "active">[]): RecommendedPlan {
486	  const minRamMB = mod.impact === "heavy" ? 4096 : mod.impact === "moderate" ? 2048 : 0;
487	  const candidates = gamePlans.filter((p) => p.active && p.ramMB >= minRamMB).sort((a, b) => a.priceCents - b.priceCents);
488	  const pick = candidates[0];
489	  return pick ? { id: pick.id, planName: pick.name, ramMB: pick.ramMB, priceCents: pick.priceCents } : null;
490	}
491	
492	export function formatDownloads(n: number | null): string | null {
493	  if (n == null) return null;
494	  if (n >= 1_000_000_000) return `${(n / 1_000_000_000).toFixed(n >= 10_000_000_000 ? 0 : 1)}B`;
495	  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(n >= 10_000_000 ? 0 : 1)}M`;
496	  if (n >= 1_000) return `${(n / 1_000).toFixed(n >= 10_000 ? 0 : 1)}K`;
497	  return String(n);
498	}
