506	/**
507	 * An honest, field-derived description for the small slice of active mods
508	 * with neither a real `description` tagline nor a `longDescription` body —
509	 * confirmed live 2026-09-20 (NxLabs overhaul, item 4): 148 of 45,766 active
510	 * mods (0.3%; mostly minimal Steam Workshop skin/map submissions and a
511	 * couple of GitHub repos with a blank `description` field) have nothing at
512	 * all from their source. This is composed only from real columns already on
513	 * the row — category, game, loader/variant, a game version, file size —
514	 * never invented marketing copy. `mod.description` and `mod.longDescription`
515	 * both being empty is the ONLY case that should ever reach this; callers
516	 * must prefer the real fields first.
517	 *
518	 * Separately: the much larger gap — 94.9% of active mods (all 32,243
519	 * Modrinth rows) have a real `description` tagline but no `longDescription`
520	 * — is NOT what this function is for. That gap exists because
521	 * scripts/backfill-modrinth-descriptions.ts, which fetches Modrinth's real
522	 * project `body` and is fully idempotent/rate-limited, has only ever been
523	 * run as a dry run against production, never with `--apply`. That is a
524	 * one-time data-backfill run to do, not a rendering fallback — see this
525	 * task's final report.
526	 */
527	export function composedDescriptionFor(
528	  mod: Pick<ModDetail, "category" | "gameFamilyLabel" | "loaders" | "appliesToVariant" | "gameVersions" | "fileBytes">
529	): string {
530	  const bits = [`A ${mod.category} for ${mod.gameFamilyLabel}`];
531	  const platform = mod.loaders[0] ?? mod.appliesToVariant;
532	  if (platform) bits.push(platform);
533	  const version = mod.gameVersions[mod.gameVersions.length - 1];
534	  if (version) bits.push(`version ${version}`);
535	  let text = `${bits.join(", ")}.`;
536	  const size = formatBytes(mod.fileBytes);
537	  if (size) text += ` ${size} download.`;
538	  return text;
539	}
540	
541	export function formatBytes(bytes: number | null): string | null {
542	  if (!bytes || bytes <= 0) return null;
543	  if (bytes >= 1024 ** 3) return `${(bytes / 1024 ** 3).toFixed(1)} GB`;
544	  if (bytes >= 1024 * 1024) return `${Math.round(bytes / (1024 * 1024))} MB`;
545	  return `${Math.max(1, Math.round(bytes / 1024))} KB`;
546	}
