548	/**
549	 * The real, authoritative download for a mod detail page. Prefers the
550	 * source's own direct file URL (same resolution `worker/game-mods.ts` uses to
551	 * install it) so a visitor gets the actual file, not just a landing page;
552	 * falls back to the mod's own project/resource page (still the real,
553	 * authoritative source — never a Nxeon-hosted mirror) when the source can't
554	 * be resolved live or isn't one of the three we know how to resolve.
555	 */
556	export async function resolveDownloadUrl(mod: Pick<GameMod, "source" | "sourceId" | "appliesToVariant" | "url">): Promise<{ url: string; direct: boolean } | null> {
557	  const fallback = mod.url ? { url: mod.url, direct: false } : null;
558	  const id = mod.sourceId ?? "";
559	  if (!id) return fallback;
560	  const UA = "Nxeon/1.0 (nxlabs-catalog)";
561	  try {
562	    if (mod.source === "modrinth") {
563	      const headers: Record<string, string> = { "User-Agent": UA };
564	      if (process.env.MODRINTH_API_KEY) headers.Authorization = process.env.MODRINTH_API_KEY;
565	      const res = await fetch(`https://api.modrinth.com/v2/project/${encodeURIComponent(id)}/version`, { headers, next: { revalidate: 3600 } });
566	      if (!res.ok) return fallback;
567	      const versions = (await res.json()) as Array<{ files: Array<{ url: string; primary: boolean }> }>;
568	      const v = versions[0];
569	      const file = v ? (v.files.find((f) => f.primary) ?? v.files[0]) : null;
570	      return file ? { url: file.url, direct: true } : fallback;
571	    }
572	    if (mod.source === "spigotmc") {
573	      // Spiget's own download endpoint 302s to the real jar — genuinely direct.
574	      return { url: `https://api.spiget.org/v2/resources/${encodeURIComponent(id)}/download`, direct: true };
575	    }
576	    if (mod.source === "thunderstore") {
577	      const [namespace, ...rest] = id.split("-");
578	      if (!namespace || !rest.length) return fallback;
579	      const res = await fetch(`https://thunderstore.io/api/experimental/package/${encodeURIComponent(namespace)}/${encodeURIComponent(rest.join("-"))}/`, {
580	        headers: { "User-Agent": UA },
581	        next: { revalidate: 3600 },
582	      });
583	      if (!res.ok) return fallback;
584	      const pkg = (await res.json()) as { latest?: { download_url?: string } };
585	      return pkg.latest?.download_url ? { url: pkg.latest.download_url, direct: true } : fallback;
586	    }
587	  } catch {
588	    return fallback;
589	  }
590	  return fallback;
591	}
