45	/** Environment variable through which the operator names the intended database. */
46	export const TARGET_ENV_VAR = "NXEON_DB_TARGET";
47	
48	export type DbTargetDecision =
49	  | { allowed: true; database: string }
50	  | { allowed: false; database: string | null; message: string };
51	
52	/**
53	 * Extract the database NAME from a PostgreSQL connection URL.
54	 *
55	 * Returns null when the URL is absent, unparseable, or names no database. We do
56	 * not guess: a connection string we cannot read is a connection string we cannot
57	 * confirm, and the whole point here is to stop acting on unconfirmed targets.
58	 */
59	export function databaseNameFromUrl(url: string | undefined | null): string | null {
60	  if (!url) return null;
61	  let parsed: URL;
62	  try {
63	    parsed = new URL(url);
64	  } catch {
65	    return null;
66	  }
67	  if (!/^postgres(ql)?:$/.test(parsed.protocol)) return null;
68	  // pathname is "/dbname" (or "" / "/" when no database is named).
69	  const raw = parsed.pathname.replace(/^\//, "");
70	  if (!raw) return null;
71	  let name: string;
72	  try {
73	    name = decodeURIComponent(raw);
74	  } catch {
75	    // A malformed percent-escape means we cannot say what database this is.
76	    return null;
77	  }
78	  return name || null;
79	}
80	
81	/**
82	 * Decide whether a writing script may proceed.
83	 *
84	 * `declared` is what the operator said (NXEON_DB_TARGET); `databaseUrl` is what
85	 * the environment silently resolved to. They must agree.
86	 */
87	export function decideDbTarget(opts: {
88	  databaseUrl: string | undefined | null;
89	  declared: string | undefined | null;
90	  /** Script name, used only to make the refusal message copy-pasteable. */
91	  script: string;
92	}): DbTargetDecision {
93	  const { databaseUrl, declared, script } = opts;
94	  const resolved = databaseNameFromUrl(databaseUrl);
95	
96	  if (!databaseUrl) {
97	    return {
98	      allowed: false,
99	      database: null,
100	      message:
101	        `Refusing to run ${script}: DATABASE_URL is not set.\n` +
102	        `Nothing was written. Set DATABASE_URL and ${TARGET_ENV_VAR} to the same database.`,
103	    };
104	  }
105	
106	  if (!resolved) {
107	    return {
108	      allowed: false,
109	      database: null,
110	      message:
111	        `Refusing to run ${script}: DATABASE_URL does not name a PostgreSQL database.\n` +
112	        `Nothing was written. Could not determine a database name from the connection string,\n` +
113	        `so there is no target to confirm against ${TARGET_ENV_VAR}.`,
114	    };
115	  }
116	
117	  const want = (declared ?? "").trim();
118	  if (!want) {
119	    return {
120	      allowed: false,
121	      database: resolved,
122	      message:
123	        `Refusing to run ${script}: ${TARGET_ENV_VAR} is not set.\n` +
124	        `Nothing was written.\n\n` +
125	        `This environment resolves to the database: ${resolved}\n\n` +
126	        `If that is genuinely the database you meant to write to, say so explicitly:\n` +
127	        `    ${TARGET_ENV_VAR}=${resolved} <your command>\n\n` +
128	        `Check it first. DATABASE_URL is resolved from a .env file that dotenv finds by\n` +
129	        `walking up from the Prisma client's REAL location — which, if node_modules is a\n` +
130	        `symlink, is not the tree you are standing in.`,
131	    };
132	  }
133	
134	  if (want !== resolved) {
135	    return {
136	      allowed: false,
137	      database: resolved,
138	      message:
139	        `Refusing to run ${script}: the database does not match what you asked for.\n` +
140	        `Nothing was written.\n\n` +
141	        `  ${TARGET_ENV_VAR} (what you asked for)  : ${want}\n` +
142	        `  DATABASE_URL    (what it resolved to): ${resolved}\n\n` +
143	        `These disagree, so one of them is wrong and it is not safe to guess which.\n` +
144	        `The usual cause is a .env being picked up from a different tree than the one you\n` +
145	        `are working in (a symlinked node_modules will do it). Confirm with:\n` +
146	        `    node -e 'console.log(process.env.DATABASE_URL)'`,
147	    };
148	  }
149	
150	  return { allowed: true, database: resolved };
151	}
152	
153	/**
154	 * Enforce the decision, or exit non-zero having written nothing.
155	 *
156	 * Exits rather than throwing: a throw from a top-level `main()` that lacks a
157	 * `.catch` becomes an unhandled rejection, which prints a stack trace and buries
158	 * the one sentence the operator needs to read.
159	 */
160	export function assertDbTarget(script: string): string {
161	  const decision = decideDbTarget({
162	    databaseUrl: process.env.DATABASE_URL,
163	    declared: process.env[TARGET_ENV_VAR],
164	    script,
165	  });
166	  if (!decision.allowed) {
167	    console.error(`\n${decision.message}\n`);
168	    process.exit(1);
169	  }
170	  console.log(`[${script}] target database confirmed: ${decision.database}`);
171	  return decision.database;
172	}
