/**
 * Tiny, dependency-free pagination helper shared across server-paginated
 * listings (originally the admin tables; NxLabs's StoreBrowser at 32k+ rows
 * per family uses it too, 2026-09-19 — see lib/mods-catalog.ts).
 *
 * Given the (already-awaited) searchParams and a total row count, it clamps the
 * requested `?page=` into range and returns the Prisma `skip`/`take` window plus
 * the resolved page number and total page count for rendering controls.
 *
 * Not a Server Action — a plain synchronous helper, safe to import anywhere.
 */
export type PageInfo = {
  skip: number;
  take: number;
  page: number;
  pages: number;
  perPage: number;
  total: number;
};

export function paginate(
  searchParams: { page?: string | string[] } | undefined,
  total: number,
  perPage = 25
): PageInfo {
  const per = Math.max(1, Math.floor(perPage) || 25);
  const pages = Math.max(1, Math.ceil(Math.max(0, total) / per));

  const rawParam = Array.isArray(searchParams?.page)
    ? searchParams?.page[0]
    : searchParams?.page;
  const raw = Number(rawParam ?? 1);
  const requested = Number.isFinite(raw) ? Math.floor(raw) : 1;
  const page = Math.min(Math.max(1, requested), pages);

  return { skip: (page - 1) * per, take: per, page, pages, perPage: per, total };
}

/**
 * Build a query string that preserves existing filters while setting `page`.
 * Values are stringified/encoded; nullish and empty values are dropped.
 */
export function pageHref(
  base: string,
  params: Record<string, string | number | undefined | null>,
  page: number
): string {
  const usp = new URLSearchParams();
  for (const [k, v] of Object.entries(params)) {
    if (v === undefined || v === null || v === "") continue;
    usp.set(k, String(v));
  }
  usp.set("page", String(page));
  const qs = usp.toString();
  return qs ? `${base}?${qs}` : base;
}

/**
 * Like `pageHref`, but for building a full set of filter/sort/page links from
 * one place (StoreBrowser's search box, sort tabs, category chips, and
 * pager all point at the same route). Page 1 and any empty/undefined value
 * are omitted so the default view keeps a clean, canonical URL.
 */
export function buildHref(
  base: string,
  params: Record<string, string | number | undefined | null>
): string {
  const usp = new URLSearchParams();
  for (const [k, v] of Object.entries(params)) {
    if (v === undefined || v === null || v === "") continue;
    if (k === "page" && Number(v) <= 1) continue;
    usp.set(k, String(v));
  }
  const qs = usp.toString();
  return qs ? `${base}?${qs}` : base;
}

