/**
 * TEMP perf-measurement script — real timings against the real production
 * GameMod catalogue, to find the true bottleneck behind /mods and
 * /dashboard/nxlabs taking 10-15s. Read-only. Delete after use.
 *
 * Run:
 *   NXEON_DB_TARGET=nxeon npx tsx scripts/_tmp-mods-catalog-perf.ts
 */
import { assertDbTarget } from "./db-target-guard";

assertDbTarget("_tmp-mods-catalog-perf");

import { db } from "../lib/db";
import {
  listCatalogFamilies,
  queryCatalogMods,
  listFeaturedMods,
  listTopDownloadedMods,
  listRecentlyUpdatedMods,
  listTopRatedMods,
  totalDownloadsFor,
  listCategoryCounts,
} from "../lib/mods-catalog";

async function time<T>(label: string, fn: () => Promise<T>): Promise<T> {
  const t0 = Date.now();
  const result = await fn();
  const ms = Date.now() - t0;
  console.log(`${ms.toString().padStart(7)}ms  ${label}`);
  return result;
}

async function main() {
  console.log("\n=== Row counts ===");
  await time("GameMod.count() total", () => db.gameMod.count());
  await time("GameMod.count() active+upstreamOk", () => db.gameMod.count({ where: { active: true, upstreamOk: true } }));
  await time("GameMod.count() minecraft family", () => db.gameMod.count({ where: { gameFamily: "minecraft" } }));
  await time("ModRating.count() total", () => db.modRating.count());
  await time("Server.count() total", () => db.server.count());

  console.log("\n=== Individual function timings (cross-game, homepage shape) ===");
  await time("listCatalogFamilies()", () => listCatalogFamilies());
  await time("queryCatalogMods({}) sort=featured page=1", () => queryCatalogMods({}));
  await time("totalDownloadsFor()", () => totalDownloadsFor());
  await time("listFeaturedMods(undefined, 12)", () => listFeaturedMods(undefined, 12));
  await time("listTopDownloadedMods(undefined, 12)", () => listTopDownloadedMods(undefined, 12));
  await time("listRecentlyUpdatedMods(undefined, 12)", () => listRecentlyUpdatedMods(undefined, 12));
  await time("listTopRatedMods(undefined, 12)", () => listTopRatedMods(undefined, 12));

  console.log("\n=== Individual function timings (per-family = minecraft, the 32k-row family) ===");
  await time("listCategoryCounts('minecraft')", () => listCategoryCounts("minecraft"));
  await time("queryCatalogMods({family:'minecraft'}) sort=featured page=1", () => queryCatalogMods({ family: "minecraft" }));
  await time("totalDownloadsFor('minecraft')", () => totalDownloadsFor("minecraft"));
  await time("listFeaturedMods('minecraft')", () => listFeaturedMods("minecraft"));
  await time("listTopDownloadedMods('minecraft')", () => listTopDownloadedMods("minecraft"));
  await time("listRecentlyUpdatedMods('minecraft')", () => listRecentlyUpdatedMods("minecraft"));
  await time("listTopRatedMods('minecraft')", () => listTopRatedMods("minecraft"));

  console.log("\n=== Other sorts (StoreBrowser tabs) ===");
  await time("queryCatalogMods({sort:'downloads'})", () => queryCatalogMods({ sort: "downloads" }));
  await time("queryCatalogMods({sort:'latest'})", () => queryCatalogMods({ sort: "latest" }));
  await time("queryCatalogMods({sort:'rating'})", () => queryCatalogMods({ sort: "rating" }));
  await time("queryCatalogMods({q:'sword'})", () => queryCatalogMods({ q: "sword" }));

  console.log("\n=== Full Promise.all as the marketing /mods homepage actually runs it ===");
  const tAll0 = Date.now();
  await Promise.all([
    listCatalogFamilies(),
    queryCatalogMods({}),
    totalDownloadsFor(),
    listFeaturedMods(undefined, 12),
    listTopDownloadedMods(undefined, 12),
    listRecentlyUpdatedMods(undefined, 12),
    listTopRatedMods(undefined, 12),
  ]);
  console.log(`${(Date.now() - tAll0).toString().padStart(7)}ms  TOTAL Promise.all (marketing /mods homepage, 7 calls)`);

  console.log("\n=== Full Promise.all as the per-family page actually runs it (minecraft) ===");
  const tFam0 = Date.now();
  await Promise.all([
    listCategoryCounts("minecraft"),
    queryCatalogMods({ family: "minecraft" }),
    totalDownloadsFor("minecraft"),
    listFeaturedMods("minecraft"),
    listTopDownloadedMods("minecraft"),
    listRecentlyUpdatedMods("minecraft"),
    listTopRatedMods("minecraft"),
  ]);
  console.log(`${(Date.now() - tFam0).toString().padStart(7)}ms  TOTAL Promise.all (per-family /mods/games/minecraft, 7 calls)`);

  console.log("\n=== EXPLAIN ANALYZE: the real WHERE/ORDER BY combos ===");
  const explainFeatured = await db.$queryRawUnsafe<{ "QUERY PLAN": string }[]>(
    `EXPLAIN (ANALYZE, BUFFERS) SELECT * FROM "GameMod" WHERE active = true AND "upstreamOk" = true ORDER BY featured DESC, downloads DESC, popularity DESC, name ASC LIMIT 24 OFFSET 0`
  );
  console.log("\n-- featured sort, cross-game --");
  console.log(explainFeatured.map((r) => r["QUERY PLAN"]).join("\n"));

  const explainDownloads = await db.$queryRawUnsafe<{ "QUERY PLAN": string }[]>(
    `EXPLAIN (ANALYZE, BUFFERS) SELECT * FROM "GameMod" WHERE active = true AND "upstreamOk" = true AND downloads IS NOT NULL ORDER BY downloads DESC, name ASC LIMIT 12`
  );
  console.log("\n-- top-downloaded rail, cross-game --");
  console.log(explainDownloads.map((r) => r["QUERY PLAN"]).join("\n"));

  const explainRecent = await db.$queryRawUnsafe<{ "QUERY PLAN": string }[]>(
    `EXPLAIN (ANALYZE, BUFFERS) SELECT * FROM "GameMod" WHERE active = true AND "upstreamOk" = true AND "upstreamUpdatedAt" IS NOT NULL ORDER BY "upstreamUpdatedAt" DESC LIMIT 12`
  );
  console.log("\n-- recently-updated rail, cross-game --");
  console.log(explainRecent.map((r) => r["QUERY PLAN"]).join("\n"));

  const explainCount = await db.$queryRawUnsafe<{ "QUERY PLAN": string }[]>(
    `EXPLAIN (ANALYZE, BUFFERS) SELECT count(*) FROM "GameMod" WHERE active = true AND "upstreamOk" = true`
  );
  console.log("\n-- count() for pagination total, cross-game --");
  console.log(explainCount.map((r) => r["QUERY PLAN"]).join("\n"));

  const explainSum = await db.$queryRawUnsafe<{ "QUERY PLAN": string }[]>(
    `EXPLAIN (ANALYZE, BUFFERS) SELECT sum(downloads) FROM "GameMod" WHERE active = true AND "upstreamOk" = true`
  );
  console.log("\n-- totalDownloadsFor() SUM, cross-game --");
  console.log(explainSum.map((r) => r["QUERY PLAN"]).join("\n"));

  const explainFamily = await db.$queryRawUnsafe<{ "QUERY PLAN": string }[]>(
    `EXPLAIN (ANALYZE, BUFFERS) SELECT * FROM "GameMod" WHERE active = true AND "upstreamOk" = true AND "gameFamily" = 'minecraft' ORDER BY featured DESC, downloads DESC, popularity DESC, name ASC LIMIT 24 OFFSET 0`
  );
  console.log("\n-- featured sort, minecraft family only --");
  console.log(explainFamily.map((r) => r["QUERY PLAN"]).join("\n"));

  await db.$disconnect();
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
