1	import Link from "next/link";
2	import type { ModSummary } from "@/lib/mods-catalog";
3	import type { CatalogSort } from "@/lib/mods-catalog";
4	import { resolveDownloadUrl } from "@/lib/mods-catalog";
5	import { buildHref } from "@/lib/pagination";
6	import { ModCard } from "./ModCard";
7	import { QuickAddButton, type QuickAddServer } from "./QuickAddButton";
8	import { IconSearch, IconArrow } from "./icons";
9	
10	/**
11	 * The interactive core of NxLabs's browse experience — search, chip
12	 * filtering, sort, and paging. Until 2026-09-19 all four ran client-side
13	 * (`useState`/`useMemo`) over the whole array the server component fetched
14	 * up front, which was genuinely fine at ~124 hand-seeded rows and quietly
15	 * broken the moment a real bulk import (scripts/import-modrinth-catalog.ts)
16	 * landed 32,000+ rows in one family: the server capped what it fetched at
17	 * 400, so there was no page 2 at all, AND the search box's own placeholder
18	 * ("Search mods, plugins, and more…") promises to search the catalogue, not
19	 * whatever 400-or-fewer rows happened to already be loaded — a client-side
20	 * `.filter()` over a partial array would silently under-report or entirely
21	 * miss real matches outside that window.
22	 *
23	 * So this is now a Server Component: `mods` is just the current page,
24	 * already filtered/sorted/paginated by `lib/mods-catalog.ts`'s
25	 * `queryCatalogMods()`, and every control here is a plain link or a native
26	 * GET `<form>` that re-requests the page with new searchParams — the same
27	 * pattern this codebase already uses for /blog's search+pager
28	 * (app/blog/page.tsx) and the admin tables (lib/pagination.ts). No client
29	 * JS is required for the store to work at all; QuickAddButton (the one
30	 * genuinely interactive bit — installing onto a real server) stays its own
31	 * small Client Component underneath.
32	 */
33	export type SortKey = CatalogSort;
34	
35	const SORTS: { key: SortKey; label: string }[] = [
36	  { key: "featured", label: "Featured" },
37	  { key: "downloads", label: "Most Downloaded" },
38	  { key: "latest", label: "Latest" },
39	  { key: "rating", label: "Top Rated" },
40	];
