42	export async function StoreBrowser({
43	  mods,
44	  total,
45	  page,
46	  totalPages,
47	  perPage,
48	  chips,
49	  chipField,
50	  activeChipKey,
51	  basePath,
52	  browsePath,
53	  q,
54	  sort,
55	  showGameBadge = false,
56	  showCategoryLabel = true,
57	  serversByFamily,
58	  deployHref,
59	  searchPlaceholder = "Search mods, plugins, and more…",
60	  emptyLabel = "No mods match your filters yet.",
61	}: {
62	  /** The current page's rows only — already the real, server-side filtered/sorted/paginated set. */
63	  mods: ModSummary[];
64	  /** Real total row count for the active filters (not just this page). */
65	  total: number;
66	  page: number;
67	  totalPages: number;
68	  perPage: number;
69	  /**
70	   * Real, DB-wide counts (never derived from `mods`, which is only one
71	   * page). When `href` is set, the chip navigates to a different route
72	   * entirely (the cross-game pages point family chips at the real
73	   * `/games/[family]` pages instead of re-filtering in place); otherwise it
74	   * links to this same route with `?category=` set.
75	   */
76	  chips: { key: string; label: string; count: number; href?: string }[];
77	  chipField: "gameFamily" | "category";
78	  /** Which chip (by key) is the active filter — only meaningful when chipField is "category"; gameFamily chips always navigate away instead. */
79	  activeChipKey?: string;
80	  /** Detail-page route prefix — `${basePath}/${mod.gameFamily}/${mod.slug}`. */
81	  basePath: string;
82	  /**
83	   * This BROWSE page's own path (no query string) — search/sort/chip/pager
84	   * links are all built from it. Usually the same as `basePath` (the two
85	   * cross-game homepages), but the per-family pages keep mod detail links
86	   * under the shared `/mods/[family]/[slug]` (or portal equivalent) route
87	   * while this page itself lives at `/mods/games/[family]` — hence the split.
88	   */
89	  browsePath?: string;
90	  /** Current `?q=`. */
91	  q?: string;
92	  /** Current `?sort=`. */
