94	  showGameBadge?: boolean;
95	  /** See ModCard's own comment — item 7 of the 2026-09-20 NxLabs overhaul. Defaults true; per-family pages (chipField "category") pass false. */
96	  showCategoryLabel?: boolean;
97	  /** Portal only: this viewer's eligible servers per game family, for the QuickAddButton row. */
98	  serversByFamily?: Record<string, QuickAddServer[]>;
99	  /** Portal only: where "order one" points when there's no matching server. */
