107	
108	  /** Build a link on this same route, preserving q/sort/category unless overridden. Omitting `page` resets to page 1 — the right default whenever the filter itself changes. */
109	  const hrefFor = (next: { page?: number; sort?: SortKey; category?: string | null; q?: string }) =>
110	    buildHref(ownPath, {
