116	
117	  const rangeFrom = total === 0 ? 0 : (page - 1) * perPage + 1;
118	  const rangeTo = total === 0 ? 0 : Math.min(page * perPage, total);
119	
120	  /**
121	   * Real per-mod download destination — the same resolveDownloadUrl() the
122	   * mod detail page's own "Download file" / "View on X" button calls,
123	   * reused here so the card's button goes to the identical, correct,
124	   * per-source URL. Resolved in parallel for the whole (already paginated,
125	   * max CATALOG_PAGE_SIZE-row) page rather than one by one; the underlying
126	   * fetches carry `next: { revalidate: 3600 }`, so repeat views of the same
127	   * mod within an hour hit Next's data cache instead of re-hitting Modrinth/
128	   * Thunderstore/Spiget.
129	   */
130	  const downloadResults = await Promise.all(mods.map((m) => resolveDownloadUrl(m)));
131	  const downloadByModId = new Map(mods.map((m, i) => [m.id, downloadResults[i]]));
132	
133	  return (
134	    <div>
135	      <div className="mb-5 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
136	        <form method="get" action={ownPath} className="relative w-full sm:max-w-xs">
137	          <IconSearch
138	            className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-[var(--fg-muted)]"
139	            size={16}
