150	          {chipField === "category" && activeChipKey && <input type="hidden" name="category" value={activeChipKey} />}
151	        </form>
152	        <div className="flex flex-wrap gap-1 rounded-full border border-white/10 p-1">
153	          {SORTS.map((s) => (
154	            <Link
155	              key={s.key}
156	              href={hrefFor({ sort: s.key })}
157	              className={`rounded-full px-3 py-1.5 text-xs font-medium transition-colors ${
158	                activeSort === s.key ? "bg-brand-500 text-white" : "text-[var(--fg-muted)] hover:text-[var(--fg)]"
159	              }`}
160	            >
161	              {s.label}
162	            </Link>
163	          ))}
164	        </div>
165	      </div>
166	
167	      {/* Item 5 of the 2026-09-20 NxLabs overhaul: the cross-game "gameFamily"
168	          chip row (All / Minecraft (32,251) / Valheim (1,238) / …) duplicated
169	          the game-catalogue carousel every page that renders this already has
170	          higher up — removed here. Category chips (chipField: "category", a
171	          per-family page's Content/Tweaks/Building/… filter) are a genuinely
172	          different, still-useful axis and stay. */}
173	      {chipField === "category" && chips.length > 0 && (
174	        <div className="mb-6 flex flex-wrap gap-2">
175	          <Link
176	            href={hrefFor({ category: null })}
177	            className={`rounded-full border px-4 py-1.5 text-sm ${
178	              !activeChipKey ? "border-brand-400 bg-brand-500/10 text-brand-300" : "border-white/10 text-[var(--fg-muted)] hover:border-white/20"
179	            }`}
180	          >
181	            All
182	          </Link>
183	          {chips.map((c) => (
184	            <Link
185	              key={c.key}
186	              href={c.href ?? hrefFor({ category: c.key })}
187	              className={`rounded-full border px-4 py-1.5 text-sm ${
188	                activeChipKey === c.key ? "border-brand-400 bg-brand-500/10 text-brand-300" : "border-white/10 text-[var(--fg-muted)] hover:border-white/20"
189	              }`}
190	            >
191	              {c.label} ({c.count})
192	            </Link>
193	          ))}
194	        </div>
195	      )}
196	
197	      {/* Item 8 of the 2026-09-20 NxLabs overhaul: a real anchor for the
198	          Pager's Prev/Next/numbered links to target (see Pager below, which
199	          appends `#nxlabs-results` to every page link) so paging keeps the
200	          visitor here instead of jumping to the very top of the page —
201	          Next's Link already scrolls to a matching id on navigation, same as
202	          a plain <a href="#..."> would; `scroll-mt-24` clears the sticky
203	          72px header so the grid doesn't land tucked underneath it. */}
204	      <div id="nxlabs-results" className="scroll-mt-24">
205	      {mods.length === 0 ? (
206	        <p className="py-12 text-center text-sm text-[var(--fg-muted)]">{emptyLabel}</p>
207	      ) : (
208	        <>
209	          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
210	            {mods.map((mod) => {
211	              const matching = serversByFamily?.[mod.gameFamily] ?? [];
212	              // Only the portal grids (which know who's signed in) pass
213	              // serversByFamily at all — the public /mods pages render the
214	              // card with just its download button and no server-action row.
215	              const footer = !serversByFamily ? undefined : matching.length > 0 ? (
216	                <QuickAddButton modId={mod.id} servers={matching} />
217	              ) : (
218	                <div className="flex shrink-0 items-center gap-1.5">
219	                  <span className="text-xs text-tx-mute">No matching server</span>
220	                  <a href={deployHref ?? "/dashboard/deploy"} className="btn-primary py-1 text-xs">
221	                    Order server
222	                  </a>
223	                </div>
224	              );
225	              return (
226	                <ModCard
227	                  key={mod.id}
228	                  mod={mod}
229	                  href={`${basePath}/${mod.gameFamily}/${mod.slug}`}
230	                  showGameBadge={showGameBadge}
231	                  showCategoryLabel={showCategoryLabel}
232	                  footer={footer}
233	                  download={downloadByModId.get(mod.id) ?? null}
234	                />
235	              );
236	            })}
237	          </div>
238	
239	          <Pager page={page} totalPages={totalPages} total={total} rangeFrom={rangeFrom} rangeTo={rangeTo} hrefFor={hrefFor} />
240	        </>
241	      )}
242	      </div>
243	    </div>
244	  );
245	}
246	
247	/** Real Prev/Next + numbered pager, plus honest "X–Y of N mods" copy — no fake page counts. */
248	function Pager({
249	  page,
250	  totalPages,
251	  total,
252	  rangeFrom,
253	  rangeTo,
254	  hrefFor,
255	}: {
256	  page: number;
257	  totalPages: number;
258	  total: number;
259	  rangeFrom: number;
260	  rangeTo: number;
261	  hrefFor: (next: { page: number }) => string;
262	}) {
263	  const linkCls =
264	    "inline-flex h-9 min-w-9 items-center justify-center gap-1.5 rounded-lg border border-white/10 bg-white/[0.03] px-3 text-sm font-medium text-[var(--fg-muted)] transition-colors hover:border-brand-400/50 hover:text-[var(--fg)]";
265	  const disabledCls =
266	    "inline-flex h-9 min-w-9 items-center justify-center gap-1.5 rounded-lg border border-white/[0.06] bg-transparent px-3 text-sm font-medium text-[var(--fg-muted)]/40 cursor-not-allowed";
267	
268	  const windowStart = Math.max(1, page - 2);
269	  const windowEnd = Math.min(totalPages, page + 2);
270	  const pages: number[] = [];
271	  for (let i = windowStart; i <= windowEnd; i++) pages.push(i);
272	
273	  // Item 8 fix: land back on the results grid (`#nxlabs-results`, rendered
274	  // by StoreBrowser above), not the page's very top — see that anchor's own
275	  // comment.
276	  const pageHrefFor = (next: { page: number }) => `${hrefFor(next)}#nxlabs-results`;
277	
278	  return (
279	    <div className="mt-8 flex flex-col items-center gap-3">
280	      <p className="text-xs text-[var(--fg-muted)]">
281	        {total === 0 ? "0 mods" : `${rangeFrom.toLocaleString()}–${rangeTo.toLocaleString()} of ${total.toLocaleString()} mods`}
282	      </p>
283	      {totalPages > 1 && (
284	        <nav className="flex flex-wrap items-center justify-center gap-2" aria-label="Mods pagination">
285	          {page > 1 ? (
286	            <Link href={pageHrefFor({ page: page - 1 })} rel="prev" className={linkCls} aria-label="Previous page">
287	              <IconArrow size={13} className="rotate-180" /> Prev
288	            </Link>
289	          ) : (
290	            <span className={disabledCls} aria-hidden>
291	              <IconArrow size={13} className="rotate-180" /> Prev
292	            </span>
293	          )}
294	
295	          {windowStart > 1 && (
296	            <>
297	              <Link href={pageHrefFor({ page: 1 })} className={linkCls}>
298	                1
299	              </Link>
300	              {windowStart > 2 && <span className="px-1 text-[var(--fg-muted)]">…</span>}
301	            </>
302	          )}
303	
304	          {pages.map((n) =>
305	            n === page ? (
306	              <span
307	                key={n}
308	                aria-current="page"
309	                className="inline-flex h-9 min-w-9 items-center justify-center rounded-lg border border-brand-500/50 bg-brand-500/15 px-3 text-sm font-semibold text-brand-300"
310	              >
311	                {n}
312	              </span>
313	            ) : (
314	              <Link key={n} href={pageHrefFor({ page: n })} className={linkCls}>
315	                {n}
316	              </Link>
317	            )
318	          )}
319	
320	          {windowEnd < totalPages && (
321	            <>
322	              {windowEnd < totalPages - 1 && <span className="px-1 text-[var(--fg-muted)]">…</span>}
323	              <Link href={pageHrefFor({ page: totalPages })} className={linkCls}>
324	                {totalPages}
325	              </Link>
326	            </>
327	          )}
328	
329	          {page < totalPages ? (
330	            <Link href={pageHrefFor({ page: page + 1 })} rel="next" className={linkCls} aria-label="Next page">
331	              Next <IconArrow size={13} />
332	            </Link>
333	          ) : (
334	            <span className={disabledCls} aria-hidden>
335	              Next <IconArrow size={13} />
336	            </span>
337	          )}
338	        </nav>
339	      )}
340	    </div>
341	  );
342	}
