/**
 * TEMP perf-measurement script — real timings of resolveDownloadUrl() against
 * the REAL external sources (Modrinth/Thunderstore APIs), called once per
 * mod card on every StoreBrowser grid render (up to CATALOG_PAGE_SIZE=24
 * mods per page, on EVERY /mods and /dashboard/nxlabs page load — see
 * components/mods/StoreBrowser.tsx's `Promise.all(mods.map(resolveDownloadUrl))`).
 * Read-only (no writes to any DB). Delete after use.
 *
 * Run:
 *   NXEON_DB_TARGET=nxeon npx tsx scripts/_tmp-resolve-download-perf.ts
 */
import { assertDbTarget } from "./db-target-guard";
assertDbTarget("_tmp-resolve-download-perf");

import { db } from "../lib/db";
import { queryCatalogMods, resolveDownloadUrl } from "../lib/mods-catalog";

async function main() {
  console.log(`MODRINTH_API_KEY set: ${Boolean(process.env.MODRINTH_API_KEY)}`);

  // The exact page the marketing/portal /mods homepage renders by default:
  // featured sort, page 1, cross-game, CATALOG_PAGE_SIZE=24 rows.
  const page = await queryCatalogMods({});
  console.log(`\nPage 1 (default featured sort) has ${page.mods.length} mods.`);
  const bySource: Record<string, number> = {};
  for (const m of page.mods) bySource[m.source] = (bySource[m.source] ?? 0) + 1;
  console.log("Sources on this page:", bySource);

  console.log("\n=== Timing resolveDownloadUrl() ONE AT A TIME (serial) for this page's mods ===");
  const serialStart = Date.now();
  for (const m of page.mods) {
    const t0 = Date.now();
    const r = await resolveDownloadUrl(m);
    console.log(`  ${(Date.now() - t0).toString().padStart(6)}ms  source=${m.source.padEnd(14)} name=${m.name.slice(0, 40)} -> ${r ? (r.direct ? "direct" : "fallback") : "null"}`);
  }
  console.log(`TOTAL serial: ${Date.now() - serialStart}ms for ${page.mods.length} mods\n`);

  console.log("=== Timing resolveDownloadUrl() via Promise.all (EXACTLY what StoreBrowser does) ===");
  const parallelStart = Date.now();
  const results = await Promise.all(page.mods.map((m) => resolveDownloadUrl(m)));
  console.log(`TOTAL Promise.all: ${Date.now() - parallelStart}ms for ${page.mods.length} mods (this is what blocks EVERY /mods and /dashboard/nxlabs page render)`);
  console.log(`Resolved: ${results.filter((r) => r?.direct).length} direct, ${results.filter((r) => r && !r.direct).length} fallback, ${results.filter((r) => !r).length} null`);

  // Also check the downloads-sort page (StoreBrowser's "Most Downloaded" tab), which is
  // Modrinth-dominated (32k+ Modrinth rows, the vast majority of the catalogue).
  console.log("\n=== Same test, sort=downloads (Modrinth-heavy page, since Modrinth has 32k+ of the 45k rows) ===");
  const page2 = await queryCatalogMods({ sort: "downloads" });
  const bySource2: Record<string, number> = {};
  for (const m of page2.mods) bySource2[m.source] = (bySource2[m.source] ?? 0) + 1;
  console.log("Sources on this page:", bySource2);
  const parallelStart2 = Date.now();
  await Promise.all(page2.mods.map((m) => resolveDownloadUrl(m)));
  console.log(`TOTAL Promise.all: ${Date.now() - parallelStart2}ms for ${page2.mods.length} mods`);

  await db.$disconnect();
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

/**
 * TEMP follow-up — worst case for resolveDownloadUrl(): a page whose 24 rows
 * are almost entirely Modrinth (the family with 32k+ of the 45k catalogue
 * rows), which is what actually renders on /mods/games/minecraft and
 * /dashboard/nxlabs/games/minecraft. Read-only. Delete after use.
 *
 * Run:
 *   NXEON_DB_TARGET=nxeon npx tsx scripts/_tmp-resolve-download-perf2.ts
 */
import { assertDbTarget } from "./db-target-guard";
assertDbTarget("_tmp-resolve-download-perf2");

import { db } from "../lib/db";
import { queryCatalogMods, resolveDownloadUrl } from "../lib/mods-catalog";

async function run(label: string, page: Awaited<ReturnType<typeof queryCatalogMods>>) {
  const bySource: Record<string, number> = {};
  for (const m of page.mods) bySource[m.source] = (bySource[m.source] ?? 0) + 1;
  console.log(`\n--- ${label}: ${page.mods.length} mods, sources: ${JSON.stringify(bySource)} ---`);
  const t0 = Date.now();
  const results = await Promise.all(page.mods.map((m) => resolveDownloadUrl(m)));
  console.log(`TOTAL Promise.all: ${Date.now() - t0}ms (direct=${results.filter((r) => r?.direct).length})`);
}

async function main() {
  await run("minecraft, featured sort, page 1", await queryCatalogMods({ family: "minecraft" }));
  await run("minecraft, downloads sort, page 1", await queryCatalogMods({ family: "minecraft", sort: "downloads" }));
  await run("minecraft, latest sort, page 1", await queryCatalogMods({ family: "minecraft", sort: "latest" }));
  await run("cross-game, latest sort, page 1", await queryCatalogMods({ sort: "latest" }));
  await run("cross-game, rating sort, page 1", await queryCatalogMods({ sort: "rating" }));
  await db.$disconnect();
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

/**
 * TEMP — checks GameMod table health after the 370x bulk-import growth
 * (124 -> 45,766 rows in one session): is autovacuum/ANALYZE stats current,
 * how big is the table/indexes really, and does Postgres have accurate
 * row-count estimates. Read-only. Delete after use.
 *
 * Run:
 *   NXEON_DB_TARGET=nxeon npx tsx scripts/_tmp-gamemod-table-health.ts
 */
import { assertDbTarget } from "./db-target-guard";
assertDbTarget("_tmp-gamemod-table-health");

import { db } from "../lib/db";

async function main() {
  const stats = await db.$queryRawUnsafe<any[]>(`
    SELECT relname, n_live_tup, n_dead_tup, last_vacuum, last_autovacuum, last_analyze, last_autoanalyze
    FROM pg_stat_user_tables WHERE relname IN ('GameMod', 'ModRating')
  `);
  console.log("=== pg_stat_user_tables ===");
  console.table(stats);

  const sizes = await db.$queryRawUnsafe<any[]>(`
    SELECT relname AS table, pg_size_pretty(pg_total_relation_size(relid)) AS total_size,
           pg_size_pretty(pg_relation_size(relid)) AS table_size,
           pg_size_pretty(pg_indexes_size(relid)) AS index_size
    FROM pg_catalog.pg_statio_user_tables WHERE relname IN ('GameMod', 'ModRating')
  `);
  console.log("\n=== table/index sizes ===");
  console.table(sizes);

  const indexes = await db.$queryRawUnsafe<any[]>(`
    SELECT indexname, indexdef FROM pg_indexes WHERE tablename = 'GameMod'
  `);
  console.log("\n=== existing GameMod indexes ===");
  for (const idx of indexes) console.log(`  ${idx.indexname}: ${idx.indexdef}`);

  const settings = await db.$queryRawUnsafe<any[]>(`
    SELECT name, setting, unit FROM pg_settings WHERE name IN ('shared_buffers', 'work_mem', 'effective_cache_size', 'max_connections')
  `);
  console.log("\n=== relevant postgres settings ===");
  console.table(settings);

  await db.$disconnect();
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

