export type ResolvedDownload = { url: string; direct: boolean } | null;

/**
 * The synchronous half of download resolution — every source EXCEPT
 * modrinth/thunderstore resolves with no network call at all (spigotmc's
 * Spiget endpoint is a constructed URL, everything else is just `mod.url`).
 * Returns `undefined` for modrinth/thunderstore specifically, meaning "a
 * live external API call is required" — callers that can't afford to block
 * on that (see StoreBrowser.tsx) use this to render immediately for the
 * ~50% of the catalogue that needs no network at all, and defer the rest to
 * an on-demand client resolve.
 *
 * REAL PERFORMANCE FIX (2026-09-21): `resolveDownloadUrl` below used to be
 * called via `Promise.all` for EVERY mod card in StoreBrowser's grid (up to
 * `CATALOG_PAGE_SIZE`=24 per /mods and /dashboard/nxlabs page load). That was
 * a real, harmless-looking pattern when the catalogue was ~124 hand-seeded
 * rows with few resolvable `sourceId`s; the moment the Modrinth bulk import
 * landed 32,000+ real rows, most default/browse pages became Modrinth-
 * dominated, and every single page load started firing up to 24 concurrent,
 * uncached, un-timed-out HTTPS calls to api.modrinth.com as part of server
 * rendering — measured live against production at 1-2.2s of REAL added
 * latency per page load (see docs/DOCUMENTATION.md's 2026-09-21 entry for
 * the exact numbers), with no upper bound if Modrinth itself is ever slow.
 * Splitting the sync-resolvable 50%+ of sources out, and deferring the
 * network-bound rest to a click-triggered resolve (DownloadButton.tsx +
 * lib/actions-mods.ts's resolveModDownloadAction), removes ALL of that from
 * the server-render critical path — a card the visitor never clicks now
 * costs zero external requests, instead of one whether it's clicked or not.
 */
export function resolveDownloadUrlSync(mod: Pick<GameMod, "source" | "sourceId" | "appliesToVariant" | "url">): ResolvedDownload | undefined {
  const fallback: ResolvedDownload = mod.url ? { url: mod.url, direct: false } : null;
  const id = mod.sourceId ?? "";
  if (!id) return fallback;
  if (mod.source === "modrinth" || mod.source === "thunderstore") return undefined;
  if (mod.source === "spigotmc") {
    // Spiget's own download endpoint 302s to the real jar — genuinely direct, no fetch needed to know that.
    return { url: `https://api.spiget.org/v2/resources/${encodeURIComponent(id)}/download`, direct: true };
  }
  return fallback;
}

/**
 * The real, authoritative download for a mod detail page. Prefers the
 * source's own direct file URL (same resolution `worker/game-mods.ts` uses to
 * install it) so a visitor gets the actual file, not just a landing page;
 * falls back to the mod's own project/resource page (still the real,
 * authoritative source — never a Nxeon-hosted mirror) when the source can't
 * be resolved live or isn't one of the three we know how to resolve.
 *
 * Fine to call eagerly for ONE mod (the detail pages do exactly that) — the
 * cost that mattered was calling it for a whole page of cards at once, see
 * `resolveDownloadUrlSync` above. Every live fetch below carries a 5s
 * timeout (`AbortSignal.timeout`) so a slow/unresponsive upstream can never
 * hang this past a bounded worst case — there was no timeout at all before
 * 2026-09-21, so a degraded Modrinth/Thunderstore response could block a
 * caller indefinitely.
 */
export async function resolveDownloadUrl(mod: Pick<GameMod, "source" | "sourceId" | "appliesToVariant" | "url">): Promise<ResolvedDownload> {
  const sync = resolveDownloadUrlSync(mod);
  if (sync !== undefined) return sync;

  const fallback: ResolvedDownload = mod.url ? { url: mod.url, direct: false } : null;
  const id = mod.sourceId ?? "";
  const UA = "Nxeon/1.0 (nxlabs-catalog)";
  try {
    if (mod.source === "modrinth") {
      const headers: Record<string, string> = { "User-Agent": UA };
      if (process.env.MODRINTH_API_KEY) headers.Authorization = process.env.MODRINTH_API_KEY;
      const res = await fetch(`https://api.modrinth.com/v2/project/${encodeURIComponent(id)}/version`, {
        headers,
        next: { revalidate: 3600 },
        signal: AbortSignal.timeout(5000),
      });
      if (!res.ok) return fallback;
      const versions = (await res.json()) as Array<{ files: Array<{ url: string; primary: boolean }> }>;
      const v = versions[0];
      const file = v ? (v.files.find((f) => f.primary) ?? v.files[0]) : null;
      return file ? { url: file.url, direct: true } : fallback;
    }
    if (mod.source === "thunderstore") {
      const [namespace, ...rest] = id.split("-");
      if (!namespace || !rest.length) return fallback;
      const res = await fetch(`https://thunderstore.io/api/experimental/package/${encodeURIComponent(namespace)}/${encodeURIComponent(rest.join("-"))}/`, {
        headers: { "User-Agent": UA },
        next: { revalidate: 3600 },
        signal: AbortSignal.timeout(5000),
      });
      if (!res.ok) return fallback;
      const pkg = (await res.json()) as { latest?: { download_url?: string } };
      return pkg.latest?.download_url ? { url: pkg.latest.download_url, direct: true } : fallback;
    }
  } catch {
    return fallback;
  }
  return fallback;
}

