"use client";

import { useState, useTransition } from "react";
import { resolveModDownloadAction } from "@/lib/actions-mods";
import { SOURCE_LABEL } from "@/lib/mods-catalog";
import { IconDownload } from "./icons";

/**
 * Click-to-resolve download button for the ~50% of the catalogue
 * (modrinth/thunderstore) whose real download URL needs a live external API
 * call — see lib/mods-catalog.ts's `resolveDownloadUrlSync` and
 * StoreBrowser.tsx's own comment for the full story: until 2026-09-21 that
 * call ran server-side for EVERY visible card on every /mods and
 * /dashboard/nxlabs page load (up to 24 concurrent requests to
 * api.modrinth.com per render), measured at 1-2.2s of added page latency.
 *
 * Paying that cost only when a visitor actually clicks "Download" — instead
 * of for every card whether it's clicked or not — is the fix. One extra
 * round trip on click is a completely different (and far smaller, in
 * aggregate) cost than 24 round trips on every page view.
 */
export function DownloadButton({ modId, source }: { modId: string; source: string }) {
  const [pending, startTransition] = useTransition();
  const [result, setResult] = useState<{ url: string; direct: boolean } | null | undefined>(undefined);

  if (result === null) {
    // Resolved, and there's genuinely nothing downloadable — matches the
    // plain <a>-less case ModCard already renders for a null `download`.
    return <span />;
  }

  if (result) {
    // Already resolved this click — render the real link so a second click
    // (or a middle-click/ctrl-click to open in a background tab) behaves
    // like a normal anchor instead of re-resolving.
    return (
      <a
        href={result.url}
        target="_blank"
        rel="noopener noreferrer nofollow"
        className="btn-secondary shrink-0 py-1 text-xs"
      >
        <IconDownload size={12} />
        {result.direct ? "Download" : `View on ${SOURCE_LABEL[source] ?? source}`}
      </a>
    );
  }

  return (
    <button
      type="button"
      className="btn-secondary shrink-0 py-1 text-xs"
      disabled={pending}
      onClick={() =>
        startTransition(async () => {
          const resolved = await resolveModDownloadAction(modId);
          setResult(resolved);
          if (resolved?.url) window.open(resolved.url, "_blank", "noopener,noreferrer");
        })
      }
    >
      <IconDownload size={12} />
      {pending ? "Resolving…" : "Download"}
    </button>
  );
}

