/**
 * TEMP — proves the new composite indexes (added to prisma/schema.prisma,
 * not yet applied anywhere) actually fix the Seq Scan + Sort EXPLAIN showed
 * earlier, WITHOUT persisting any schema change to production: creates each
 * index inside a transaction, runs EXPLAIN ANALYZE, then ROLLS BACK. Nothing
 * is left behind. Read-only from the database's point of view. Delete after use.
 *
 * Run:
 *   NXEON_DB_TARGET=nxeon npx tsx scripts/_tmp-verify-index-plan.ts
 */
import { assertDbTarget } from "./db-target-guard";
assertDbTarget("_tmp-verify-index-plan");

import { db } from "../lib/db";

async function main() {
  try {
    await db.$transaction(
      async (tx) => {
        console.log("Creating the 3 candidate indexes inside an uncommitted transaction...");
        await tx.$executeRawUnsafe(
          `CREATE INDEX "tmp_verify_featured_idx" ON "GameMod" (featured DESC, downloads DESC, popularity DESC, name ASC)`
        );
        await tx.$executeRawUnsafe(`CREATE INDEX "tmp_verify_downloads_idx" ON "GameMod" (downloads DESC, name ASC)`);
        await tx.$executeRawUnsafe(`CREATE INDEX "tmp_verify_createdat_idx" ON "GameMod" ("createdAt" DESC)`);

        console.log("\n-- featured sort (default homepage view), WITH the new index --");
        const p1 = await tx.$queryRawUnsafe<{ "QUERY PLAN": string }[]>(
          `EXPLAIN (ANALYZE, BUFFERS) SELECT * FROM "GameMod" WHERE active = true AND "upstreamOk" = true ORDER BY featured DESC, downloads DESC, popularity DESC, name ASC LIMIT 24 OFFSET 0`
        );
        console.log(p1.map((r) => r["QUERY PLAN"]).join("\n"));

        console.log("\n-- downloads sort, WITH the new index --");
        const p2 = await tx.$queryRawUnsafe<{ "QUERY PLAN": string }[]>(
          `EXPLAIN (ANALYZE, BUFFERS) SELECT * FROM "GameMod" WHERE active = true AND "upstreamOk" = true AND downloads IS NOT NULL ORDER BY downloads DESC, name ASC LIMIT 12`
        );
        console.log(p2.map((r) => r["QUERY PLAN"]).join("\n"));

        console.log("\n-- latest (createdAt) sort, WITH the new index --");
        const p3 = await tx.$queryRawUnsafe<{ "QUERY PLAN": string }[]>(
          `EXPLAIN (ANALYZE, BUFFERS) SELECT * FROM "GameMod" WHERE active = true AND "upstreamOk" = true ORDER BY "createdAt" DESC LIMIT 24`
        );
        console.log(p3.map((r) => r["QUERY PLAN"]).join("\n"));

        console.log("\n-- minecraft-family featured sort, WITH the new index (per-family case) --");
        const p4 = await tx.$queryRawUnsafe<{ "QUERY PLAN": string }[]>(
          `EXPLAIN (ANALYZE, BUFFERS) SELECT * FROM "GameMod" WHERE active = true AND "upstreamOk" = true AND "gameFamily" = 'minecraft' ORDER BY featured DESC, downloads DESC, popularity DESC, name ASC LIMIT 24 OFFSET 0`
        );
        console.log(p4.map((r) => r["QUERY PLAN"]).join("\n"));

        console.log("\nRolling back — no schema change is persisted.");
        throw new Error("__ROLLBACK_ONLY__");
      },
      { timeout: 30000 }
    );
  } catch (err: any) {
    if (err?.message !== "__ROLLBACK_ONLY__") throw err;
  }

  // Prove nothing was left behind.
  const remaining = await db.$queryRawUnsafe<any[]>(
    `SELECT indexname FROM pg_indexes WHERE tablename = 'GameMod' AND indexname LIKE 'tmp_verify_%'`
  );
  console.log(`\nIndexes still present matching tmp_verify_%: ${remaining.length} (expect 0)`);

  await db.$disconnect();
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

/**
 * TEMP — "after" measurement: StoreBrowser's grid now calls
 * resolveDownloadUrlSync (no network) instead of resolveDownloadUrl (up to
 * 24 concurrent live external calls). Confirms the fix actually removes the
 * network cost from the render path. Read-only. Delete after use.
 *
 * Run:
 *   NXEON_DB_TARGET=nxeon npx tsx scripts/_tmp-resolve-download-after.ts
 */
import { assertDbTarget } from "./db-target-guard";
assertDbTarget("_tmp-resolve-download-after");

import { db } from "../lib/db";
import { queryCatalogMods, resolveDownloadUrlSync } from "../lib/mods-catalog";

async function run(label: string, page: Awaited<ReturnType<typeof queryCatalogMods>>) {
  const t0 = Date.now();
  const resolved = page.mods.map((m) => resolveDownloadUrlSync(m));
  const ms = Date.now() - t0;
  const pending = resolved.filter((r) => r === undefined).length;
  console.log(`${ms.toString().padStart(4)}ms  ${label} (${page.mods.length} mods, ${pending} deferred to click-resolve, 0 network calls made)`);
}

async function main() {
  await run("cross-game, featured sort, page 1", await queryCatalogMods({}));
  await run("minecraft, featured sort, page 1 (worst case before: 2183ms)", await queryCatalogMods({ family: "minecraft" }));
  await run("minecraft, downloads sort, page 1 (worst case before: 2073ms)", await queryCatalogMods({ family: "minecraft", sort: "downloads" }));
  await db.$disconnect();
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

